1. using OpenTelemetry;
2. using OpenTelemetry.Metrics;
3. using OpenTelemetry.Trace;
4. using AspNetCoreMcpServer.Tools;
5. using AspNetCoreMcpServer.Resources;
6. using System.Net.Http.Headers;
7. 
8. var builder = WebApplication.CreateBuilder(args);
9. var allowedOrigins = builder.Configuration.GetSection("Mcp:AllowedOrigins").Get<string[]>() ?? ["http://localhost:5173"];
10. 
11. // Only enable CORS if you intentionally want browser-based cross-origin access to this server.
12. // Keep the allowlist narrowly scoped to known origins. Broad CORS settings weaken security.
13. builder.Services.AddCors(options =>
14. {
15.     options.AddPolicy("McpBrowserClient", policy =>
16.     {
17.         policy.WithOrigins(allowedOrigins)
18.             .WithMethods("GET", "POST", "DELETE")
19.             // Browsers can send Accept without extra CORS configuration. These are the MCP-specific
20.             // and non-safelisted headers the browser-based client needs for stateful Streamable HTTP.
21.             .WithHeaders("Content-Type", "MCP-Protocol-Version", "Mcp-Session-Id")
22.             .WithExposedHeaders("Mcp-Session-Id");
23.     });
24. });
25. 
26. // Note: This sample uses SampleLlmTool which calls server.AsSamplingChatClient() to send
27. // a server-to-client sampling request. This requires stateful (session-based) mode. Set
28. // Stateless = false explicitly for forward compatibility in case the default changes.
29. // See https://csharp.sdk.modelcontextprotocol.io/concepts/sessions/sessions.html for details.
30. builder.Services.AddMcpServer()
31.     .WithHttpTransport(o => o.Stateless = false)
32.     .WithTools<EchoTool>()
33.     .WithTools<SampleLlmTool>()
34.     .WithTools<WeatherTools>()
35.     .WithResources<SimpleResourceType>();
36. 
37. builder.Services.AddOpenTelemetry()
38.     .WithTracing(b => b.AddSource("*")
39.         .AddAspNetCoreInstrumentation()
40.         .AddHttpClientInstrumentation())
41.     .WithMetrics(b => b.AddMeter("*")
42.         .AddAspNetCoreInstrumentation()
43.         .AddHttpClientInstrumentation())
44.     .WithLogging()
45.     .UseOtlpExporter();
46. 
47. // Configure HttpClientFactory for weather.gov API
48. builder.Services.AddHttpClient("WeatherApi", client =>
49. {
50.     client.BaseAddress = new Uri("https://api.weather.gov");
51.     client.DefaultRequestHeaders.UserAgent.Add(new ProductInfoHeaderValue("weather-tool", "1.0"));
52. });
53. 
54. var app = builder.Build();
55. 
56. app.UseCors();
57. app.MapMcp().RequireCors("McpBrowserClient");
58. 
59. app.Run();
60.

