using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public class DevOpsTools
{
    [McpServerTool, Description("Returns the health status of the service")]
    public static object HealthCheck()
    {
        return new
        {
            Status = "healthy",
            Uptime = TimeSpan.FromMinutes(42).ToString(),
            Timestamp = DateTimeOffset.UtcNow
        };
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
        => $"Echo: {message}";
}

