using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResourceType]
public class ConfigResources
{
    // A direct resource — no URI parameters, listed via resources/list.
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "app-settings",
        MimeType = "application/json")]
    [Description("Returns the current application configuration")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "production",
            MaxRetries = 3,
            TimeoutSeconds = 30,
            Features = new { DarkMode = true, BetaAccess = false }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    // A resource template — URI contains a parameter, listed via resources/templates/list.
    // The {section} segment is automatically bound to the method parameter.
    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "app-settings-section",
        MimeType = "application/json")]
    [Description("Returns configuration for a specific section (e.g. 'database', 'logging')")]
    public static string GetSettingsSection(string section)
    {
        var sections = new Dictionary<string, object>
        {
            ["database"] = new { Host = "db.example.com", Port = 5432, PoolSize = 20 },
            ["logging"]  = new { Level = "Information", Sink = "console", RetainDays = 7 },
            ["cache"]    = new { Provider = "redis", Host = "cache.example.com", TtlSeconds = 300 },
        };

        if (!sections.TryGetValue(section, out var data))
        {
            throw new ArgumentException($"Unknown configuration section: '{section}'");
        }

        return JsonSerializer.Serialize(data, new JsonSerializerOptions { WriteIndented = true });
    }
}

